107	                                start..self.text_position(),
108	                            )
109	                                .with_hint("Use a regular whitespace character instead."),
110	                        )
111	                    }
112	                },
113	
114	                _ => break,
115	            }
116	        }
117	    }
118	
119	    /// Asserts that the lexer is currently positioned at `byte`
120	    fn assert_byte(&self, byte: u8) {
121	        debug_assert_eq!(self.source().as_bytes()[self.position()], byte);
122	    }
123	
124	    /// Advances the position by one and returns the next byte value
125	    fn next_byte(&mut self) -> Option<u8> {
126	        self.advance(1);
127	        self.current_byte()
128	    }
129	
130	    /// Returns `true` if the parser is at or passed the end of the file.
131	    fn is_eof(&self) -> bool {
132	        self.position() >= self.source().len()
