18	/// Lexer context for different markdown parsing modes
19	#[derive(Debug, Copy, Clone, Eq, PartialEq, Default)]
20	pub enum MarkdownLexContext {
21	    /// Normal markdown parsing with inline element detection.
22	    #[default]
23	    Regular,
24	    /// Inside fenced code block - no markdown parsing.
25	    #[expect(dead_code)]
26	    FencedCodeBlock,
27	    /// Inside HTML block - minimal markdown parsing.
28	    #[expect(dead_code)]
29	    HtmlBlock,
30	    /// Inside link definition (after `]:`). Whitespace separates destination from title.
31	    LinkDefinition,
32	    /// Inside inline code span. Backslashes are literal per CommonMark §6.1.
33	    CodeSpan,
34	    /// Emphasis delimiter processing. Emit single STAR/UNDERSCORE tokens for partial consumption.
35	    EmphasisInline,
36	    /// Inside thematic break parts decomposition.
37	    /// In this context, break markers (`*`, `-`, `_`) emit as individual
38	    /// STAR/MINUS/UNDERSCORE tokens and whitespace emits as MD_INDENT_CHAR,
39	    /// instead of aggregating into MD_THEMATIC_BREAK_LITERAL.
40	    ThematicBreakParts,
41	    /// Inside ATX heading content. Behaves like Regular but does NOT bundle
42	    /// trailing spaces with the newline into MD_HARD_LINE_LITERAL. Instead,
43	    /// spaces are emitted as MD_TEXTUAL_LITERAL and the newline is emitted
44	    /// separately. This allows the parser to consume trailing spaces as
45	    /// Whitespace trivia without swallowing the newline.
46	    HeadingContent,
47	}
