111	        self.source
112	    }
113	
114	    fn current(&self) -> Self::Kind {
115	        self.current_kind
116	    }
117	
118	    fn current_start(&self) -> TextSize {
119	        self.current_start
120	    }
121	
122	    fn next_token(&mut self, context: Self::LexContext) -> Self::Kind {
123	        self.current_start = self.text_position();
124	        self.current_flags = TokenFlags::empty();
125	
126	        let kind = match self.current_byte() {
127	            Some(current) => self.consume_token(current, context),
128	            None => EOF,
129	        };
130	
131	        self.current_flags
132	            .set(TokenFlags::PRECEDING_LINE_BREAK, self.after_newline);
133	        self.current_kind = kind;
134	
135	        // Reset after_newline for non-trivia tokens, except NEWLINE itself.
136	        // NEWLINE sets after_newline=true in consume_newline() and we preserve that.
137	        // This ensures the *next* token (after NEWLINE) has PRECEDING_LINE_BREAK set.
138	        if !kind.is_trivia()
139	            && kind != NEWLINE
140	            && kind != MD_HARD_LINE_LITERAL
141	            && !(kind == MD_TEXTUAL_LITERAL
142	                && self.after_newline
143	                && self.current_text_is_whitespace())
