171	        let new_pos = u32::from(position) as usize;
172	
173	        self.position = new_pos;
174	        self.current_kind = current_kind;
175	        self.current_start = current_start;
176	        self.current_flags = current_flags;
177	        self.after_newline = after_line_break;
178	        self.unicode_bom_length = unicode_bom_length;
179	        self.diagnostics.truncate(diagnostics_pos as usize);
180	    }
