39	impl<'source> MarkdownTokenSource<'source> {
40	    /// Creates a new token source.
41	    pub(crate) fn new(lexer: BufferedLexer<MarkdownSyntaxKind, MarkdownLexer<'source>>) -> Self {
42	        MarkdownTokenSource {
43	            lexer,
44	            trivia_list: vec![],
45	        }
46	    }
47	    /// Creates a new token source for the given string
48	    pub fn from_str(source: &'source str) -> Self {
49	        let lexer = MarkdownLexer::from_str(source);
50	
51	        let buffered = BufferedLexer::new(lexer);
52	        let mut source = MarkdownTokenSource::new(buffered);
53	
54	        source.next_non_trivia_token(MarkdownLexContext::default(), true);
55	        source
56	    }
57	
58	    fn next_non_trivia_token(&mut self, context: MarkdownLexContext, first_token: bool) {
59	        let mut trailing = !first_token;
60	
61	        loop {
62	            let kind = self.lexer.next_token(context);
63	
64	            let trivia_kind = TriviaPieceKind::try_from(kind);
65	
66	            match trivia_kind {
67	                Err(_) => {
68	                    // Not trivia
69	                    break;
70	                }
71	                Ok(trivia_kind) => {
72	                    if trivia_kind.is_newline() {
73	                        trailing = false;
74	                    }
75	
76	                    self.trivia_list
77	                        .push(Trivia::new(trivia_kind, self.current_range(), trailing));
78	                }
79	            }
80	        }
81	    }
