1	//! Thematic break parsing for Markdown (CommonMark §4.1).
2	//!
3	//! A thematic break (horizontal rule) is a line consisting of three or more
4	//! matching `-`, `_`, or `*` characters, optionally with spaces between them.
5	//!
6	//! # Examples
7	//!
8	//! ```markdown
9	//! ---
10	//! ***
11	//! ___
12	//! - - -
13	//! *  *  *
14	//! ```
15	
16	use crate::parser::MarkdownParser;
17	use crate::syntax::MAX_BLOCK_PREFIX_INDENT;
18	use biome_markdown_syntax::MarkdownSyntaxKind::*;
19	use biome_markdown_syntax::T;
20	use biome_parser::{
21	    Parser,
22	    prelude::ParsedSyntax::{self, *},
23	};
24	
25	/// CommonMark requires 3 or more matching characters for thematic breaks.
26	const THEMATIC_BREAK_MIN_CHARS: usize = 3;
27	
28	pub(crate) fn at_thematic_break_block(p: &mut MarkdownParser) -> bool {
29	    p.lookahead(|p| {
30	        if p.at_line_start() || p.at_start_of_input() {
31	            if p.line_start_leading_indent() > MAX_BLOCK_PREFIX_INDENT {
32	                return false;
33	            }
34	            p.skip_line_indent(MAX_BLOCK_PREFIX_INDENT);
35	            return p.at(MD_THEMATIC_BREAK_LITERAL);
36	        }
37	
38	        // Special case: we may not be at line start if a list marker was consumed
39	        // (e.g., `- * * *` where `-` was consumed as a list marker).
40	        // Check if the remaining content is a thematic break pattern.
41	        is_thematic_break_pattern(p)
42	    })
43	}
44	
45	/// Check if the remaining content forms a thematic break pattern.
46	///
47	/// Per CommonMark §4.1, a thematic break is 3 or more matching characters
48	/// (`*`, `-`, or `_`) on a line by itself, optionally with spaces between them.
49	fn is_thematic_break_pattern(p: &mut MarkdownParser) -> bool {
50	    // Skip leading whitespace
51	    while p.at(MD_TEXTUAL_LITERAL) && p.cur_text().chars().all(|c| c == ' ' || c == '\t') {
52	        p.bump(MD_TEXTUAL_LITERAL);
53	    }
54	
55	    // Check for lexer-produced thematic break token
56	    if p.at(MD_THEMATIC_BREAK_LITERAL) {
57	        return true;
58	    }
59	
60	    // If the entire line segment is a single textual literal, validate it directly.
61	    if p.at(MD_TEXTUAL_LITERAL)
62	        && p.cur_text()
63	            .chars()
64	            .all(|c| c == ' ' || c == '\t' || c == '*' || c == '-' || c == '_')
65	    {
66	        let mut break_char = None;
67	        let mut break_count = 0usize;
68	
69	        for c in p.cur_text().chars() {
70	            if c == ' ' || c == '\t' {
71	                continue;
72	            }
73	            if let Some(existing) = break_char {
74	                if existing != c {
75	                    return false;
76	                }
77	            } else {
78	                break_char = Some(c);
79	            }
80	            break_count += 1;
81	        }
82	
83	        let has_eol = p.lookahead(|p| {
84	            p.bump(MD_TEXTUAL_LITERAL);
85	            while p.at(MD_TEXTUAL_LITERAL) && p.cur_text().chars().all(|c| c == ' ' || c == '\t') {
86	                p.bump(MD_TEXTUAL_LITERAL);
87	            }
88	            p.at(NEWLINE) || p.at(T![EOF])
89	        });
90	
91	        return break_count >= THEMATIC_BREAK_MIN_CHARS && has_eol;
92	    }
93	
94	    // Get the break character from the first non-whitespace token.
95	    // DOUBLE_STAR / DOUBLE_UNDERSCORE count as 2 of the underlying char.
96	    let break_char = if p.at(T![*]) || p.at(T![**]) {
97	        '*'
98	    } else if p.at(T![-]) {
99	        '-'
100	    } else if p.at(UNDERSCORE) || p.at(DOUBLE_UNDERSCORE) {
101	        '_'
102	    } else if p.at(MD_TEXTUAL_LITERAL) {
103	        let text = p.cur_text();
104	        if text.len() == 1 {
105	            match text.chars().next() {
106	                Some('*') => '*',
107	                Some('-') => '-',
108	                Some('_') => '_',
109	                _ => return false,
110	            }
111	        } else {
112	            return false;
113	        }
114	    } else {
115	        return false;
116	    };
117	
118	    // Count matching characters.
119	    // DOUBLE_STAR / DOUBLE_UNDERSCORE contribute 2 to the count.
120	    let mut count = 0usize;
121	
122	    loop {
123	        let (is_break, char_count) = match break_char {
124	            '*' if p.at(T![**]) => (true, 2),
125	            '*' if p.at(T![*]) || (p.at(MD_TEXTUAL_LITERAL) && p.cur_text() == "*") => (true, 1),
126	            '-' if p.at(T![-]) || (p.at(MD_TEXTUAL_LITERAL) && p.cur_text() == "-") => (true, 1),
127	            '_' if p.at(DOUBLE_UNDERSCORE) => (true, 2),
128	            '_' if p.at(UNDERSCORE) || (p.at(MD_TEXTUAL_LITERAL) && p.cur_text() == "_") => {
129	                (true, 1)
130	            }
131	            _ => (false, 0),
132	        };
133	
134	        if is_break {
135	            count += char_count;
136	            p.bump_any();
137	            continue;
138	        }
139	
140	        // Skip whitespace between break characters
141	        if p.at(MD_TEXTUAL_LITERAL) && p.cur_text().chars().all(|c| c == ' ' || c == '\t') {
142	            p.bump(MD_TEXTUAL_LITERAL);
143	            continue;
144	        }
145	
146	        // End of line or other content
147	        break;
148	    }
149	
150	    // Valid thematic break if 3+ characters followed by end of line
151	    count >= THEMATIC_BREAK_MIN_CHARS && (p.at(NEWLINE) || p.at(T![EOF]))
152	}
153	
154	pub(crate) fn parse_thematic_break_block(p: &mut MarkdownParser) -> ParsedSyntax {
155	    if !at_thematic_break_block(p) {
156	        return Absent;
157	    }
158	    let m = p.start();
159	
160	    parse_thematic_break_parts(p);
161	
162	    Present(m.complete(p, MD_THEMATIC_BREAK_BLOCK))
163	}
164	
