579	/// Parse a paragraph block, or a setext heading if followed by an underline.
580	///
581	/// A paragraph is a sequence of non-blank lines that cannot be interpreted as
582	/// other kinds of blocks. The paragraph ends at a blank line or EOF.
583	///
584	/// If the paragraph is followed by a setext heading underline (=== or ---),
585	/// it becomes a setext heading instead.
586	///
587	/// Grammar: MdParagraph = list: MdInlineItemList hard_line: MdHardLine?
588	/// Grammar: MdSetextHeader = content: MdInlineItemList underline: 'md_setext_underline_literal'
589	pub(crate) fn parse_paragraph(p: &mut MarkdownParser) -> ParsedSyntax {
590	    let m = p.start();
591	
592	    let inline_start: usize = p.cur_range().start().into();
593	    parse_inline_item_list(p);
594	    let inline_end: usize = p.cur_range().start().into();
595	
596	    let has_inline_content = inline_has_non_whitespace(p, inline_start, inline_end);
597	    let allow_setext = has_inline_content && allow_setext_heading(p);
598	
599	    // Check if this paragraph is followed by a setext heading underline
600	    // MD_SETEXT_UNDERLINE_LITERAL is for `=` underlines
601	    // MD_THEMATIC_BREAK_LITERAL with only `-` is also a setext underline (H2)
602	    let completed = if allow_setext && p.at(MD_SETEXT_UNDERLINE_LITERAL) {
603	        let indent = real_line_indent_from_source(p);
604	        if indent < INDENT_CODE_BLOCK_SPACES {
605	            // This is a setext heading (H1 with `=`) - consume the underline
606	            p.bump(MD_SETEXT_UNDERLINE_LITERAL);
607	            m.complete(p, MD_SETEXT_HEADER)
608	        } else {
609	            // 4+ spaces of indent: not a setext underline (CommonMark §4.3)
610	            m.complete(p, MD_PARAGRAPH)
611	        }
612	    } else if allow_setext && p.at(MD_THEMATIC_BREAK_LITERAL) && is_dash_only_thematic_break(p) {
613	        let indent = real_line_indent_from_source(p);
614	        if indent < INDENT_CODE_BLOCK_SPACES {
615	            // This is a setext heading (H2 with `-`) - remap token and consume
616	            p.bump_remap(MD_SETEXT_UNDERLINE_LITERAL);
617	            m.complete(p, MD_SETEXT_HEADER)
618	        } else {
619	            // 4+ spaces of indent: not a setext underline (CommonMark §4.3)
620	            m.complete(p, MD_PARAGRAPH)
621	        }
622	    } else {
623	        m.complete(p, MD_PARAGRAPH)
624	    };
625	    Present(completed)
626	}
