648	/// Token-based check: is the current line a setext underline?
649	///
650	/// Call after consuming a NEWLINE token. Skips 0–3 columns of leading whitespace
651	/// (tabs expand to the next tab stop per CommonMark §2.2), then checks for
652	/// `MD_SETEXT_UNDERLINE_LITERAL` or a dash-only `MD_THEMATIC_BREAK_LITERAL`.
653	///
654	/// Returns `Some(bytes_consumed)` if the line is a setext underline, `None` otherwise.
655	/// The byte count includes only the whitespace tokens consumed during the indent skip,
656	/// NOT the underline token itself. Callers that track byte budgets must subtract this.
657	///
658	/// This is the shared helper for setext detection in inline contexts.
659	/// Used by `has_matching_code_span_closer`, `parse_inline_html`, and `parse_inline_item_list`.
660	///
661	/// Context safety: this function does NOT call `allow_setext_heading` because the token
662	/// stream itself encodes context. In blockquotes, `R_ANGLE` tokens appear after NEWLINE
663	/// before content, so the whitespace-only skip naturally rejects those lines. In list
664	/// items, the indent reflected in the token stream is the raw line indent, and the
665	/// `columns < 4` check correctly rejects lines with 4+ columns of leading whitespace.
666	pub(crate) fn at_setext_underline_after_newline(p: &mut MarkdownParser) -> Option<usize> {
667	    let mut columns = 0;
668	    let mut bytes_consumed = 0;
669	    while columns < INDENT_CODE_BLOCK_SPACES
670	        && p.at(MD_TEXTUAL_LITERAL)
671	        && p.cur_text().chars().all(|c| c == ' ' || c == '\t')
672	    {
673	        for c in p.cur_text().chars() {
674	            match c {
675	                ' ' => columns += 1,
676	                '\t' => columns += TAB_STOP_SPACES - (columns % TAB_STOP_SPACES),
677	                _ => {}
678	            }
679	        }
680	        bytes_consumed += p.cur_text().len();
681	        p.bump(MD_TEXTUAL_LITERAL);
682	    }
683	    if columns >= INDENT_CODE_BLOCK_SPACES {
684	        return None;
685	    }
686	    let is_setext = p.at(MD_SETEXT_UNDERLINE_LITERAL)
687	        || (p.at(MD_THEMATIC_BREAK_LITERAL) && is_dash_only_thematic_break_text(p.cur_text()));
688	    if is_setext {
689	        Some(bytes_consumed)
690	    } else {
691	        None
692	    }
693	}
