695	/// Token-based check: does an inline span of `byte_len` bytes cross a setext underline?
696	///
697	/// Walks tokens via lookahead. At each NEWLINE, delegates to
698	/// [`at_setext_underline_after_newline`] — the same detection used by
699	/// `has_matching_code_span_closer` and `parse_inline_item_list`.
700	pub(crate) fn inline_span_crosses_setext(p: &mut MarkdownParser, byte_len: usize) -> bool {
701	    p.lookahead(|p| {
702	        let mut remaining = byte_len;
703	        loop {
704	            if remaining == 0 || p.at(T![EOF]) {
705	                return false;
706	            }
707	            if p.at(NEWLINE) {
708	                let nl_len = p.cur_text().len();
709	                if nl_len > remaining {
710	                    return false;
711	                }
712	                remaining -= nl_len;
713	                p.bump(NEWLINE);
714	                if let Some(ws_bytes) = at_setext_underline_after_newline(p) {
715	                    // Only flag if the whitespace consumed is still within our span
716	                    return ws_bytes <= remaining;
717	                }
718	                continue;
719	            }
720	            let tok_len = p.cur_text().len();
721	            if tok_len > remaining {
722	                return false;
723	            }
724	            remaining -= tok_len;
725	            p.bump_any();
726	        }
727	    })
728	}
